def dedupe_contacts(rows):
    import re
    from datetime import datetime

    def normalize_email(value):
        value = value or ""
        match = re.search(r"<([^<>]*)>", value)
        if match:
            value = match.group(1)
        value = value.strip().lower()

        if value.count("@") == 1:
            local, domain = value.split("@")
            if domain in ("gmail.com", "googlemail.com"):
                local = local.split("+", 1)[0].replace(".", "")
                domain = "gmail.com"
                value = f"{local}@{domain}"
        return value

    def valid_email(value):
        if value.count("@") != 1:
            return False
        local, domain = value.split("@")
        return bool(local) and "." in domain and not domain.startswith(".") and not domain.endswith(".")

    def normalize_phone(value):
        value = value or ""
        marker = re.search(r"x|ext|#", value, flags=re.IGNORECASE)
        if marker:
            value = value[:marker.start()]
        digits = re.sub(r"\D", "", value)
        if len(digits) == 11 and digits.startswith("1"):
            digits = digits[1:]
        return digits

    def valid_phone(value):
        return len(value) == 10 and value[0] not in "01"

    def normalize_zip(value):
        value = (value or "").strip()
        if re.fullmatch(r"\d{5}-\d{4}", value):
            value = value.split("-", 1)[0]
        if re.fullmatch(r"\d{4}", value):
            value = "0" + value
        return value if re.fullmatch(r"\d{5}", value) else ""

    def normalize_name(value):
        value = (value or "").strip()
        if value and (value.isupper() or value.islower()):
            return value.title()
        return value

    def parse_updated(value):
        value = value.strip()
        for fmt in ("%Y-%m-%dT%H:%M:%S", "%Y-%m-%d", "%m/%d/%Y"):
            try:
                return datetime.strptime(value, fmt)
            except ValueError:
                pass
        raise ValueError(f"Unsupported updated value: {value!r}")

    def opted_out(value):
        return (value or "").strip().lower() in {"y", "yes", "true", "1"}

    records = []
    for index, row in enumerate(rows):
        email = normalize_email(row.get("email", ""))
        email = email if valid_email(email) else ""
        phone = normalize_phone(row.get("phone", ""))
        phone = phone if valid_phone(phone) else ""
        if not email and not phone:
            continue

        updated = parse_updated(row["updated"])
        last_name = normalize_name(row.get("last_name", ""))
        source = (row.get("source", "") or "").strip().lower()
        records.append({
            "index": index,
            "row": row,
            "email": email,
            "phone": phone,
            "first_name": normalize_name(row.get("first_name", "")),
            "last_name": last_name,
            "zip": normalize_zip(row.get("zip", "")),
            "source": source,
            "updated_dt": updated,
            "opted_out": opted_out(row.get("opted_out", "")),
            "tags": [
                tag.strip().lower()
                for tag in re.split(r"[;,]", row.get("tags", "") or "")
                if tag.strip()
            ],
        })

    # Union-find makes duplicate matching transitive.
    parent = list(range(len(records)))

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(a, b):
        ra, rb = find(a), find(b)
        if ra != rb:
            parent[rb] = ra

    by_email = {}
    by_phone_and_last = {}
    for i, record in enumerate(records):
        email = record["email"]
        if email:
            if email in by_email:
                union(i, by_email[email])
            else:
                by_email[email] = i

        phone, last_name = record["phone"], record["last_name"]
        if phone and last_name:
            key = (phone, last_name.casefold())
            if key in by_phone_and_last:
                union(i, by_phone_and_last[key])
            else:
                by_phone_and_last[key] = i

    groups = {}
    for i, record in enumerate(records):
        groups.setdefault(find(i), []).append(record)

    def choose(group, field, require_valid=False):
        candidates = [
            record for record in group
            if record[field] and (not require_valid or record[field])
        ]
        if not candidates:
            return ""
        candidates.sort(key=lambda record: (
            record["source"] != "manual",
            -record["updated_dt"].timestamp(),
            record["index"],
        ))
        return candidates[0][field]

    people = []
    for group in groups.values():
        group.sort(key=lambda record: record["index"])
        latest = max(record["updated_dt"] for record in group)
        people.append((
            group[0]["index"],
            {
                "first_name": choose(group, "first_name"),
                "last_name": choose(group, "last_name"),
                "zip": choose(group, "zip"),
                "email": choose(group, "email", require_valid=True),
                "phone": choose(group, "phone", require_valid=True),
                "source": choose(group, "source"),
                "tags": ";".join(sorted({tag for record in group for tag in record["tags"]})),
                "opted_out": "Y" if any(record["opted_out"] for record in group) else "N",
                "updated": latest.strftime("%Y-%m-%d"),
            },
        ))

    people.sort(key=lambda item: item[0])
    return [person for _, person in people]
